(function(){
  var INIT={id:'ID',url:'URL',uri:'URI',api:'API',http:'HTTP',https:'HTTPS',json:'JSON',xml:'XML',
            html:'HTML',sql:'SQL',ip:'IP',db:'DB',uuid:'UUID',cpu:'CPU',ttl:'TTL',eof:'EOF',
            ascii:'ASCII',utf8:'UTF8',sha:'SHA',md5:'MD5',ssh:'SSH',tls:'TLS',ui:'UI'};
  function pascal(s,useInit){
    var parts=String(s).replace(/[^A-Za-z0-9]+/g,' ')
      .replace(/([a-z0-9])([A-Z])/g,'$1 $2').trim().split(/\s+/);
    if(!parts[0])return 'Field';
    var out='';
    for(var i=0;i<parts.length;i++){
      var w=parts[i],lw=w.toLowerCase();
      if(useInit!==false&&INIT[lw]) out+=INIT[lw];
      else out+=w.charAt(0).toUpperCase()+w.slice(1);
    }
    if(/^[0-9]/.test(out)) out='F'+out;
    return out;
  }
  function singular(s){
    if(/ies$/.test(s)) return s.slice(0,-3)+'y';
    if(/(ses|xes|zes|ches|shes)$/.test(s)) return s.slice(0,-2);
    if(/[^s]s$/.test(s)) return s.slice(0,-1);
    return s;
  }
  function isInt(n){ return typeof n==='number'&&isFinite(n)&&Math.floor(n)===n; }

  function merge(a,b){
    if(a==null) return b;
    if(b==null) return a;
    if(a==='interface{}'||b==='interface{}') return 'interface{}';
    if(a===b) return a;
    if((a==='int64'&&b==='float64')||(a==='float64'&&b==='int64')) return 'float64';
    if(typeof a==='object'&&typeof b==='object'){
      var o={},k;
      for(k in a) o[k]=a[k];
      for(k in b) o[k]=(k in a)?merge(a[k],b[k]):b[k];
      for(k in a) if(!(k in b)) o[k]=a[k];
      return o;
    }
    return 'interface{}';
  }
  function shape(v){
    if(v===null||v===undefined) return 'interface{}';
    if(Array.isArray(v)){
      var el=null;
      for(var i=0;i<v.length;i++) el=merge(el,shape(v[i]));
      return {__arr:el==null?'interface{}':el};
    }
    var t=typeof v;
    if(t==='string') return 'string';
    if(t==='boolean') return 'bool';
    if(t==='number') return isInt(v)?'int64':'float64';
    var o={};
    for(var k in v) o[k]=shape(v[k]);
    return o;
  }

  function toGo(text,opt){
    opt=opt||{};
    var root=pascal(opt.root||'AutoGenerated');
    var data;
    try{ data=JSON.parse(text); }catch(e){ return {error:'JSON 解析失败：'+(e&&e.message||e)}; }
    var sh=shape(data);
    if(typeof sh==='string') return {error:'顶层必须是对象或数组'};
    var defs=[],seen={};
    function nameFor(base){
      var n=base,i=2;
      while(seen[n]){ n=base+i; i++; }
      seen[n]=1; return n;
    }
    function emit(obj,typeName){
      var lines=['type '+typeName+' struct {'];
      var keys=Object.keys(obj);
      for(var i=0;i<keys.length;i++){
        var k=keys[i],v=obj[k],fname=pascal(k),gtype;
        if(typeof v==='string'){ gtype=v; }
        else if(v&&v.__arr!==undefined){
          var inner=v.__arr,depth='[]';
          while(inner&&inner.__arr!==undefined){ depth+='[]'; inner=inner.__arr; }
          if(typeof inner==='string') gtype=depth+inner;
          else gtype=depth+emit(inner,nameFor(pascal(singular(k))));
        } else {
          gtype='*'+emit(v,nameFor(pascal(k)));
          if(opt.ptr===false) gtype=gtype.slice(1);
        }
        var tag='`json:"'+k+(opt.omitempty?',omitempty':'')+'"';
        if(opt.yaml) tag+=' yaml:"'+k+'"';
        tag+='`';
        lines.push('\t'+fname+' '+gtype+' '+tag);
      }
      lines.push('}');
      defs.push(lines.join('\n'));
      return typeName;
    }
    seen[root]=1;
    var top;
    if(sh.__arr!==undefined){
      var inner2=sh.__arr;
      if(typeof inner2==='string'){ defs.push('type '+root+' []'+inner2); top=root; }
      else { var nm=emit(inner2,root+'Item'); defs.push('type '+root+' []'+nm); top=root; }
    } else { top=emit(sh,root); }
    var code=defs.reverse().join('\n\n')+'\n';
    var count=(code.match(/^type /gm)||[]).length;
    return {value:{code:code,root:top,structs:count}};
  }

  var API={toGo:toGo,pascal:pascal,singular:singular,shape:shape};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__GoStructForge__=API;
})();
